import random
from fractions import Fraction

def network_pi(edges):
    """edges: list of (u, v, w), with w a whole number."""
    strength = {}
    for u, v, w in edges:
        strength[u] = strength.get(u, 0) + w
        strength[v] = strength.get(v, 0) + w
    total = sum(strength.values())
    return {node: Fraction(s, total) for node, s in strength.items()}

def return_time_mc(edges, start, steps, seed):
    """Mean number of steps between visits to start."""
    nbrs = {}
    for u, v, w in edges:
        nbrs.setdefault(u, []).append((v, w))
        nbrs.setdefault(v, []).append((u, w))
    rng = random.Random(seed)
    here, last, gaps = start, 0, []
    for t in range(1, steps + 1):
        options = nbrs[here]
        here = rng.choices([n for n, _ in options], weights=[w for _, w in options])[0]
        if here == start:
            gaps.append(t - last)
            last = t
    return sum(gaps) / len(gaps)
